lemma IsBounded.smallMinimals {H : Finset (Finset α)} {W : Finset α} {ℓ ℓ₁ : ℕ}
    (hℓ₁ : ℓ₁ = ⌊((9 : ℝ) / 10) * ℓ⌋₊) :
    IsBounded (smallMinimals H W ℓ) ℓ₁

lemma generate_union_mem {H : Finset (Finset α)} {W : Finset α} {ℓ : ℕ}
    {T : Finset {x : α // x ∉ W}}
    (hT : T ∈ generate ((smallMinimals H W ℓ).image (toSub W))) :
    ofSub W T ∪ W ∈ generate H

lemma exists_mem_subset_union {H : Finset (Finset α)} {W' S₀ : Finset α}
    (h : S₀ ∈ restrictFamily H (W' \ S₀)) (hsub : S₀ ⊆ W') :
    ∃ S ∈ H, S ⊆ W' ∧ S₀ ⊆ S

lemma card_pairs_fst {H : Finset (Finset α)} {ℓ w k : ℕ} {W : Finset α}
    (hW : W.card = w) :
    #{p ∈ largePairs H ℓ w k | p.1 = W} =
      #{S' ∈ largeMinimals H W ℓ | S'.card = k}

lemma coverCost_gt_half_of_gt_q {F : Finset (Finset α)} {p : ℝ}
    (hp : p ∈ Set.Icc 0 1) (h : expectationThreshold F < p) :
    (1 : ℝ) / 2 < coverCost p F

theorem equation_16 {H : Finset (Finset α)} {S W T R : Finset α}
    (h : IsMinimumFragment H S W T) (hR : R ∈ H) (hRsub : R ⊆ W ∪ T) :
    T ⊆ R

theorem fragment_fiber_card_le {H : Finset (Finset α)} {ell : ℕ}
    (hb : IsBounded H ell) (Z : Finset α) (m : ℕ) :
    #{T : Finset α | T.card = m ∧ T ⊆ Z ∧ T ∈ fragments H (Z \ T)} ≤ ell.choose m

theorem fragmentPairs_card_le {H : Finset (Finset α)} {ell w m : ℕ}
    (hb : IsBounded H ell) :
    #(fragmentPairs H w m) ≤ (Fintype.card α).choose (w + m) * ell.choose m

theorem entryWeight_encode {p q : ℝ} (hq : 0 < q) {e : Entry X}
    (he : e ∈ D.entries) : entryWeight p q e =
      subsetMass q (encode e).2.2 * (p*(1-q)/q) ^ (encode e).2.1.val

theorem bounded_of_finite_expectation {p : ℝ} {Lambda : Set (X → ℝ)}
    (hp : 0 < p) (hn : NonnegativeWeights Lambda)
    (hE : extendedExpectation p Lambda < ⊤) : BoundedWeights Lambda

theorem thinning (hF : D.family.Nonempty) {q r : ℝ}
    (hq : 0 ≤ q) (hq1 : q ≤ 1) (hr : 0 ≤ r) (hr1 : r ≤ 1) :
    r * expectation q (D.value hF) ≤ expectation (q*r) (D.value hF)

theorem normalized_bound (hF : D.family.Nonempty) {p : ℝ}
    (hp : 0 < p) (hp1 : p < 1) (hnot : ¬ IsPSmall p D.family) :
    1 ≤ 512 * expectation p (D.value hF)

theorem weightValues_nonempty {Lambda : Set (X → ℝ)}
    (hLambda : Lambda.Nonempty) (S : Finset X) :
    (weightValues Lambda S).Nonempty

theorem weightValues_bddAbove {Lambda : Set (X → ℝ)}
    (hnonneg : NonnegativeWeights Lambda) (hbound : BoundedWeights Lambda)
    (S : Finset X) : BddAbove (weightValues Lambda S)

theorem exists_weight_of_lt_value {Lambda : Set (X → ℝ)}
    (hLambda : Lambda.Nonempty) (hnonneg : NonnegativeWeights Lambda)
    (hbound : BoundedWeights Lambda) {S : Finset X} {a : ℝ}
    (ha : a < selectorValue Lambda S) :
    ∃ w ∈ Lambda, a < ∑ i ∈ S, w i

theorem conjecture_7_3 {p : ℝ} (hp : 0 < p) (hp1 : p < 1)
    {A : Set (Cube X)} (hA : Up A) :
    WeaklySmall ((1/2)*p) {J | measure p A < theta (1/2) A J}

theorem admissible_erase (w : X → ℝ) (A : Finset X) {d ε : ℝ} {m : ℕ}
    (h : Admissible w A d m ε) {x : X} (hx : x ∈ A) (hwx : w x ≤ ε) (hm : 0 < m) :
    Admissible w (A.erase x) d (m-1) ε

theorem feasible_unchanged_not_bad {F : Finset (Finset X)} {w : Finset X → X → ℝ}
    (hw : ∀ H ∈ F, ∑ x, w H x = 1) (a : Coloring X s) (h : Feasible F w a a) :
    ¬ BadColoring F w a

theorem bad_minimal_changed_nonempty {F : Finset (Finset X)} {w : Finset X → X → ℝ}
    (hw : ∀ H ∈ F, ∑ x, w H x = 1) {a z : Coloring X s}
    (ha : BadColoring F w a) (hz : MinimalMove F w a z) : (changed a z).Nonempty

theorem productMass_bernoulli {π : C→ℝ} (hπ : ∑c,π c=1) (φ : C→Bool) {p : ℝ}
    (hp : (∑c,if φ c=true then π c else 0)=p) (A : Set (TalagrandConjectures.Cube X)) :
    (∑a : X→C, if (fun x=>φ (a x))∈A then productMass π a else 0) = TalagrandConjectures.measure p A

theorem colorY_mean {p : ℝ} (hp : 0<p) {s : ℕ}
    (hs : p*scaleSum s ≤ 1/2) (hnext : 1/2 < p*scaleSum (s+1)) :
    (∑ c : Fin (s+1), colorProb p s c * colorY c) ≤ 5*(512:ℝ)^4*p

theorem fractional_mass {r : ℝ} (hr : 0 ≤ r) {F : Finset (Finset X)} {g : Finset X → ℝ}
    (hg : FractionalCover r F g) {H : Finset X} (hH : H ∈ F) :
    1/2 ≤ subsetMass g H

theorem conjecture_7_3 {p : ℝ} (hp : 0 < p) (hp1 : p < 1)
    {A : Set (Cube X)} (hA : Up A) :
    WeaklySmall ((1/2)*p) {J | measure p A < theta (1/2) A J}
